# https://nbformat.readthedocs.io/en/latest/format_description.html
import json

# %% ../nbs/2_messages.ipynb #7fb6a669
def cells(nbjson):
    return nbjson.get('cells', [])

# %% ../nbs/2_messages.ipynb #a356048f
def source(cell):
    return "".join(cell.get('source', ""))

# %% ../nbs/2_messages.ipynb #f736c0fb
def outputs(cell):
    return cell.get('outputs', [])

# %% ../nbs/2_messages.ipynb #6f3770f2
def msg(content: list, role='user', id:str=None, status:str=None):
    r = {'type': 'message','role': role,'content': content}
    if role == 'assistant': 
        assert id is not None and status is not None
        r['id'] = id; r['status'] = status
    return r

# %% ../nbs/2_messages.ipynb #9c20a699
def text_content(text, type='input_text'):
    r = {'type': type, 'text': text}
    if type == 'output_text': r['annotations'] = []
    return r

# %% ../nbs/2_messages.ipynb #61ad93db
def image_content(data_url): return {"type":"input_image","image_url":data_url,"detail":"auto"}

# %% ../nbs/2_messages.ipynb #b6cfefa2
# outputs
def text_outputs(cell):
    r = ""
    for o in outputs(cell):
        lines = o.get('data', {}).get('text/plain', [])
        shorter_lines = [l[:200]+'... [truncated]' if len(l) > 200 else l for l in lines]
        r+="".join(shorter_lines)
    return r

# %% ../nbs/2_messages.ipynb #5d199ab4
def all_text(cell) -> str:
    # return "\n\n".join([source(cell), text_outputs(cell)])
    # return "Cell input:\n"+source(cell)+"\nCell output:\n"+text_outputs(cell)
    i = source(cell); o=text_outputs(cell); out = ""
    if i!= "": out+="Cell input:\n"+i
    if o!="": out+="\n\nCell output:\n"+o
    return out.strip()

# %% ../nbs/2_messages.ipynb #074b5e57
def all_images(cell) -> list[str]:
    "Return list of image strings from cell"
    mime = 'image/png'
    img_encodigs = []
    # attachments -> image/png
    attachments = cell.get('attachments', {}) # dict keyed by filename
    for k, v in attachments.items():
        i = v.get(mime)
        if i is not None: img_encodigs.append(i)
    # outputs -> data
    for o in outputs(cell):
        i = o.get('data', {}).get(mime)
        if i is not None: img_encodigs.append(i)
    return img_encodigs


# %% ../nbs/2_messages.ipynb #57d09297
def cell2msg(cell):
    mime = "image/png"
    text = all_text(cell)
    images = all_images(cell)
    content = []
    tc = text_content(text)
    ics = [image_content(f"data:{mime};base64,{base64_image}") for base64_image in images]
    if tc != "": content.append(tc)
    content.extend(ics)
    return msg(content)
